// Example of a more flexible layout widget
class HeaderContentFooterLayout extends StatelessWidget {
  final Widget header;
  final Widget content;
  final Widget? footer; // Footer is optional

  const HeaderContentFooterLayout({
    Key? key,
    required this.header,
    required this.content,
    this.footer,
  }) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        header,
        Expanded(child: content),
        if (footer != null) footer!,
      ],
    );
  }
}
